insert into members(id,team,sort_order,code,company_th,company_en,owner_name,nickname,gender,is_leader,business,highlight,benefit,products,scene_idea,dialogue_th,contact,note) values ('build-sirayooth','BUILD',1,'BK27144','บริษัท ศิรายุทธ จำกัด','Sirayooth Co., Ltd.','อภิชญา ทองหนู','มด','หญิง',false,'ผู้เชี่ยวชาญระบบทำความเย็นอุตสาหกรรมมากกว่า 40 ปี ออกแบบ ติดตั้ง และบำรุงรักษาระบบทำความเย็นแอมโมเนีย (R-717) และ CO2 (R-744) แบบครบวงจร','40+ ปี 500+ โครงการ ทีมงาน 80 คน โรงงานของตัวเอง 2,700 ตร.ม. แปรรูปชิ้นงานเองเพื่อคุมคุณภาพ ทำครบตั้งแต่ออกแบบถึงติดตั้ง (One-Stop-Shop) ลูกค้าคือ CPF, Nestlé, Betagro, Big-C, Lotus''s, PTTOR','ระบบเย็นที่เชื่อถือได้ ไม่หยุดกลางคัน และคุมค่าไฟได้จริง โรงงานอาหารไม่ต้องเสี่ยงของเสียทั้งล็อต','ออกแบบระบบ (Design), บริหารโครงการ (Project), บำรุงรักษา (Maintenance), ระบบทำความเย็นแอมโมเนียและ CO2','ยืนกลางห้องเย็นอุตสาหกรรมขนาดยักษ์ แตะแผงควบคุมโฮโลแกรม ไอเย็นสีฟ้าไหลแผ่ไปทั่วห้องพร้อมกันทุกจุด ตัวเลขอุณหภูมิและค่าไฟบนจอลอยปรับลงต่อหน้า','สวัสดีค่ะ มด จาก SIRAYOOTH นะคะ เราเป็นผู้เชี่ยวชาญระบบทำความเย็นอุตสาหกรรมครบวงจร ประสบการณ์กว่า 40 ปีค่ะ',null,'⚠️ e-card ระบุเจ้าของเป็น อภิชญา (มด) หญิง แต่รูปในโฟลเดอร์เป็นผู้ชาย — ต้องเช็กว่าใครมาออกงาน') on conflict (id) do nothing;
