insert into members(id,team,sort_order,code,company_th,company_en,owner_name,nickname,gender,is_leader,business,highlight,benefit,products,scene_idea,dialogue_th,contact,note) values ('build-sp-engineering','BUILD',2,null,'บริษัท เอสพี เอ็นจิเนียริ่ง แอนด์ ซัพพลาย จำกัด','SP Engineering and Supply Co., Ltd.','ศักดิ์สิทธิ์ พะเนาไธสง',null,'ชาย',false,'วิศวกรรมและซัพพลายอุตสาหกรรม จัดหาอุปกรณ์และโซลูชันจากผู้ผลิตชั้นนำระดับโลก ก่อตั้งปี 2017','ครอบคลุม 5 กลุ่ม — ปั๊มลม, ไฟฟ้าและระบบอัตโนมัติ, ไฮดรอลิก-นิวเมติก, วาล์ว, ระบบทำความเย็นและแก๊สคอมเพรสเซอร์ · ได้ ISO 9001:2015 · เป็นตัวแทน Atlas Copco, Emerson, Parker, Danfoss, Yuken','ได้ของแท้จากแบรนด์ระดับโลกพร้อมทีมที่ติดตั้งและซ่อมบำรุงให้ ตรงเวลาทุกครั้ง (on-time, just in time, every time)','Air Compressor, Electrical & Automation, Hydraulic & Pneumatic, Valve, Refrigeration & Gas Compressor','ยืนกลางโรงงานอนาคต ยกมือขึ้น ชิ้นส่วนเครื่องจักร ปั๊มลม วาล์ว และตู้ควบคุมไฟฟ้าลอยขึ้นมาเรียงรอบตัวเป็นวงแล้วประกอบเข้าเป็นไลน์ผลิตที่เดินเครื่องได้ทันที','สวัสดีครับ ศักดิ์สิทธิ์ จาก SP Engineering & Supply นะครับ เราดูแลโซลูชันวิศวกรรมอุตสาหกรรมครบวงจร ตั้งแต่ Air Compressor ถึงระบบ Automation ครับ',null,'⚠️ ยังไม่มีรูปหน้า/โลโก้/รูปสินค้าในโฟลเดอร์เลย มีแต่ e-card') on conflict (id) do nothing;
