insert into members(id,team,sort_order,code,company_th,company_en,owner_name,nickname,gender,is_leader,business,highlight,benefit,products,scene_idea,dialogue_th,contact,note) values ('build-broroma','BUILD',3,'BK27107','บริษัท โบรโรมา (ประเทศไทย) จำกัด','Broroma (Thailand) Limited','ลักษิกา วิทยาจักษุ์','มินนี่','หญิง',false,'จำหน่ายท่อเหล็ก วาล์ว และฟิตติ้ง สำหรับงานระบบท่ออุตสาหกรรมและบอยเลอร์','ของได้มาตรฐานสากล ASTM / ASME / DIN / JIS ครบทั้งระบบในเจ้าเดียว ลูกค้าเป็นรายใหญ่อย่าง GULF, PTT GC, SCG, TPI','ซื้อที่เดียวได้ครบทั้งระบบท่อ ของเข้ากันได้หมด ส่งเร็ว ไม่ต้องวิ่งหาหลายร้าน','ท่อเหล็ก (Steel Pipe), วาล์ว (Valve), ฟิตติ้ง (Fitting), ข้องอ สามทาง หน้าแปลน','ยืนในโรงงานอนาคต กางมือออก ท่อ วาล์ว และข้อต่อทุกชิ้นลอยขึ้นจากพื้น หมุนเข้าหากันประกอบเป็นระบบท่อสมบูรณ์ในพริบตา แล้วไอน้ำแรงดันสูงพุ่งทะลุผ่านทั้งเส้นอย่างฉลุย','สวัสดีค่ะ มินนี่ จาก Broroma ประเทศไทย นะคะ เราเป็นผู้เชี่ยวชาญท่อเหล็ก วาล์ว และฟิตติ้ง สำหรับงานระบบท่อและหม้อไอน้ำค่ะ',null,'เดิมเข้าใจว่าเจ้าของเป็นผู้ชาย — e-card ระบุ ลักษิกา (มินนี่) หญิง ต้องเช็กรูปตัวละครใหม่') on conflict (id) do nothing;
