insert into members(id,team,sort_order,code,company_th,company_en,owner_name,nickname,gender,is_leader,business,highlight,benefit,products,scene_idea,dialogue_th,contact,note) values ('build-nps-plus','BUILD',4,'BK27069','เอ็นพีเอส พลัส','NPS Plus','ปฐมฤกษ์ พงษ์ชัยไกรกิติ','บีม','ชาย',true,'ลิฟต์ บันไดเลื่อน และทางลาดเลื่อน สำหรับบ้าน อาคาร และโครงการ ตั้งแต่จำหน่าย ติดตั้ง ซ่อมบำรุง ถึงบริการหลังการขาย','ประสบการณ์ 25+ ปี มาตรฐาน ISO และ CE · มีแบรนด์ลิฟต์บ้านระดับพรีเมียมของตัวเองชื่อ UP by NPS PLUS (LIFT UP YOUR LIFE)','ลิฟต์ไม่ค้าง มีทีมดูแลตลอดอายุการใช้งาน คนในอาคารขึ้นลงได้อย่างมั่นใจทุกวัน','ลิฟต์โดยสาร, ลิฟต์บ้าน UP, บันไดเลื่อน, ทางลาดเลื่อน, สัญญาบำรุงรักษา','ยืนในล็อบบี้ตึกสูงอนาคต ยกมือขึ้น ประตูลิฟต์ทั้งแถวเปิดพร้อมกันเป็นจังหวะ เส้นแสงสีส้มวิ่งขึ้นตามปล่องลิฟต์ไปจนถึงชั้นบนสุดของตึก','สวัสดีครับ บีม จาก NPS Plus นะครับ เราทำลิฟต์ บันไดเลื่อน และลิฟต์บ้าน ครบวงจรทุกขนาดอาคารครับ',null,'หัวหน้าทีม BUILD 🟠 — ยังไม่มีรูปสินค้า/ลิฟต์') on conflict (id) do nothing;
