insert into members(id,team,sort_order,code,company_th,company_en,owner_name,nickname,gender,is_leader,business,highlight,benefit,products,scene_idea,dialogue_th,contact,note) values ('build-absolute65','BUILD',5,'BK27119','แอบโซลูท 65','Absolute 65','วีรพงษ์ สมานัตตานนท์','ปอ','ชาย',false,'รับตกแต่งภายในแบบ Turnkey สำหรับคอนโด บ้าน อพาร์ตเมนต์ พูลวิลล่า และโรงแรม','งานบิลท์อินผลิตด้วยเครื่องจักร CNC ของตัวเอง ทำจบครบวงจรตั้งแต่ออกแบบถึงติดตั้ง (Turnkey) ผลงานระดับโครงการหรูอย่าง Luxe35 และ IDEO ลำสาลี','ได้บ้านที่ออกมาเหมือนแบบเป๊ะ งานเนี้ยบ ไม่ต้องคุมหลายผู้รับเหมาเอง','ตกแต่งคอนโด, บิลท์อินบ้าน, งานโรงแรมและอพาร์ตเมนต์แบบ Turnkey','ยืนในห้องเปล่าสีเทา กวาดมือไปข้างหน้า เส้นแบบสถาปัตย์เรืองแสงวิ่งไปตามผนัง แล้วเฟอร์นิเจอร์บิลท์อิน โคมไฟ และเคาน์เตอร์หินอ่อนค่อยๆ ก่อตัวขึ้นจากแสงจนกลายเป็นห้องที่จัดเสร็จสมบูรณ์','สวัสดีครับ ปอ จาก Absolute 65 นะครับ เรารับงานตกแต่งภายในแบบ Turnkey ทั้งคอนโด บ้าน และโรงแรมครับ',null,'⚠️ ยังไม่มีรูปหน้าคน และไฟล์ในโฟลเดอร์ยังไม่ได้ตั้งชื่อตามระบบ') on conflict (id) do nothing;
