insert into members(id,team,sort_order,code,company_th,company_en,owner_name,nickname,gender,is_leader,business,highlight,benefit,products,scene_idea,dialogue_th,contact,note) values ('build-leo-residence','BUILD',6,'BK27028','บริษัท เอื้อวรกมล จำกัด','LEO Residence','ชุติพงศ์ วรจรรยาวงศ์','ยัง','ชาย',false,'อพาร์ตเมนต์ให้เช่า 3 สาขา — นิคมอุตสาหกรรมอมตะซิตี้ ระยอง, สะพานสี่ ระยอง และกบินทร์บุรี','ห้องพักคุณภาพในทำเลใกล้นิคมอุตสาหกรรม ดูแลบริการเองทุกสาขา ผู้เช่าอยู่สบายจริง','พนักงานโรงงานและครอบครัวได้ห้องพร้อมอยู่ ใกล้ที่ทำงาน ไม่ต้องเสียเวลาเดินทาง','อพาร์ตเมนต์ให้เช่ารายเดือน 3 สาขา, บริการดูแลอาคาร','เดินเข้าไปในล็อบบี้อพาร์ตเมนต์ตอนค่ำ ปรบมือหนึ่งครั้ง ไฟในทุกห้องของตึกสว่างไล่ขึ้นไปทีละชั้นจนเต็มตึก แล้วหันมายิ้มให้กล้อง','สวัสดีครับ ย้ง จากเอื้อวรกมล LEO Residence นะครับ เรามีอพาร์ทเม้นท์ให้เช่า 3 สาขา รองรับทุกไลฟ์สไตล์การอยู่อาศัยครับ',null,null) on conflict (id) do nothing;
