insert into members(id,team,sort_order,code,company_th,company_en,owner_name,nickname,gender,is_leader,business,highlight,benefit,products,scene_idea,dialogue_th,contact,note) values ('make-pc-foil','MAKE',1,'BK27041','บริษัท พี.ซี. ฟอยล์ อินดัสตรีส์ จำกัด','P.C. Foil Industries Co., Ltd.','ณัฐพงศ์ ตั้งปัญญาวงศ์','วิว','ชาย',true,'ผลิตฟอยล์และบรรจุภัณฑ์ — ม้วนฟอยล์ ฝาฟอยล์ ซองลามิเนต และฟอยล์แผงยา ส่งอุตสาหกรรมอาหาร เครื่องดื่ม และยา','ลูกค้าเป็นแบรนด์ใหญ่ระดับประเทศ (เจ้าสัว, ไวไว, SFC, ไทย-เดนมาร์ค, องค์การเภสัชกรรม, Cafe Amazon) ได้มาตรฐาน SGS, ACFS และ Green Industry','อาหารและยาที่บรรจุปิดผนึกได้แน่นสนิท ปลอดภัย และสวยพร้อมวางขายทันที','ม้วนฟอยล์, ฝาฟอยล์, ซองลามิเนต, ฟอยล์แผงยา','จับม้วนฟอยล์เงินขนาดยักษ์แล้วคลี่ออกด้วยแรงเดียว ริบบิ้นแสงโลหะพลิ้วรอบตัว สะบัดมือครั้งเดียวริบบิ้นบินไปปิดผนึกถ้วยและซองบนสายพานทั้งแถวพร้อมกันจนวาววับ','สวัสดีครับ วิว จาก P.C. Foil Industries นะครับ เราเป็นผู้ผลิตบรรจุภัณฑ์ฟอยล์ ฝาฟอยล์ และซองลามิเนตครบวงจรครับ',null,'หัวหน้าทีม MAKE 🟣 · มีคลิป v1 แล้ว — บทเดิมเน้น ''ทำให้ดูพรีเมียม'' แต่ธุรกิจจริงเน้นฟอยล์ปิดผนึกอาหาร/ยา ควร regen') on conflict (id) do nothing;
