insert into members(id,team,sort_order,code,company_th,company_en,owner_name,nickname,gender,is_leader,business,highlight,benefit,products,scene_idea,dialogue_th,contact,note) values ('make-foilmaster','MAKE',2,'BK27085','ฟอยล์มาสเตอร์ (ประเทศไทย)','Foilmaster (Thailand) Ltd.','ภคภรณ์ ภัคสุขชัย','เกรซ','หญิง',false,'ผลิตและจำหน่ายฟอยล์สำหรับฉลาก บรรจุภัณฑ์ งานพิมพ์ผ้าและเครื่องหนัง รวมถึงฟอยล์ป้องกันการปลอมแปลง','มี Digital foil ที่ไม่มีขั้นต่ำ ทำให้แบรนด์เล็กก็สั่งได้ · มีฟอยล์กันปลอมและสติกเกอร์ void · ฟอยล์ติดผ้า PU flex ผ่านมาตรฐาน OEKO-TEX · คำโปรย ''YOU''VE GOT A FRIEND IN US''','แบรนด์ดูมีราคาขึ้นทันที และของแท้ถูกปลอมยากขึ้น','Hot & Cold foil, Digital foil, ฟอยล์ป้องกันการปลอมแปลง, ริบบอนพิมพ์วันหมดอายุ, บล็อกทองเหลือง, Void sticker, PU flex, Textile foil','วางฝ่ามือลงบนฉลากขวดสีดำเปล่า แสงทองวิ่งออกจากใต้ฝ่ามือไปตามลวดลาย ปั๊มเป็นลายทองนูนขึ้นมาต่อหน้า พอเอียงขวด ลายกันปลอมแบบโฮโลแกรมเปล่งประกายขึ้นมาซ้อนอีกชั้น','สวัสดีค่ะ เกรซ จาก Foilmaster ประเทศไทย นะคะ เราทำฟอยล์ตกแต่งบรรจุภัณฑ์ ทั้ง Hot Foil, Cold Foil และ Digital Foil ค่ะ',null,'มีคลิป v2 แล้ว (ไม่มีซับ) รอรีวิว') on conflict (id) do nothing;
