insert into members(id,team,sort_order,code,company_th,company_en,owner_name,nickname,gender,is_leader,business,highlight,benefit,products,scene_idea,dialogue_th,contact,note) values ('make-quality-flexpack','MAKE',3,'BK27020','บริษัท ควอลิตี้ เฟล็คแพ็ค จำกัด','Quality Flexpack Co., Ltd.','ฉัตรกาญจน์ ถนัดค้า','ทอม','ชาย',false,'ผลิตบรรจุภัณฑ์พลาสติกสำหรับภาคอุตสาหกรรม — กระสอบ ถุงจัมโบ้ พรีสลิง ถุงหูหิ้ว และถุงเป่า','ประสบการณ์กว่า 25 ปีในวงการบรรจุภัณฑ์พลาสติก เข้าใจงานอุตสาหกรรมจริง ได้ ISO9001, ISO14001, GHP, HACCP และ Green Industry','บรรจุภัณฑ์ที่รับน้ำหนักได้จริง ไม่ฉีกไม่ขาดระหว่างขนส่ง ในราคาที่แข่งขันได้','กระสอบ, Jumbo Bag, Pre Sling, ถุงหูหิ้ว, ถุงเป่า','ยืนในโกดังอนาคต ยกมือขึ้น ถุงจัมโบ้ใบมหึมาที่บรรจุเม็ดพลาสติกเต็มลอยขึ้นกลางอากาศ แสงม่วงวิ่งไปตามตะเข็บทุกเส้นจนแน่นหนา แล้วถุงลงวางบนพาเลทอย่างมั่นคงโดยไม่มีรอยฉีก','สวัสดีครับ ทอม จาก Quality Flexpack นะครับ เราเป็นผู้ผลิตบรรจุภัณฑ์พลาสติกและ Jumbo Bag มากว่า 25 ปีครับ',null,'⚠️ คลิปเดิมทำเป็นซองอาหาร ซึ่งผิด — ธุรกิจจริงคือกระสอบ/ถุงจัมโบ้อุตสาหกรรม ต้อง regen') on conflict (id) do nothing;
