insert into members(id,team,sort_order,code,company_th,company_en,owner_name,nickname,gender,is_leader,business,highlight,benefit,products,scene_idea,dialogue_th,contact,note) values ('make-mastercrafts','MAKE',4,'BK27032','บริษัท จิงเจิ้ง จำกัด','Mastercraftsgift by Jingzhung / Soonestbiz','ญาดาณดา ภาณุทัตธนาคุณ','เชอรี่','หญิง',false,'โรงงานผลิตกระเป๋า งาน Garment และของพรีเมียม พร้อมบริการ Fulfillment ครบวงจร (คลัง คัดแยก แพ็ก จัดส่ง B2B/B2C)','เป็นโรงงานผลิตเองโดยตรง มีช่างแพตเทิร์นขึ้นตัวอย่างได้ทันที · เป็น VENDOR LIST CLASS A ของหน่วยงานชั้นนำ · มีหนังสือรับรองผลงานภาครัฐมูลค่ากว่า 100 ล้านบาท · รองรับวัสดุรักษ์โลก rPET/ESG','คุยที่เดียวจบตั้งแต่ออกแบบถึงส่งของถึงมือลูกค้าปลายทาง ไม่ต้องประสานหลายเจ้า','OEM/ODM, ของพรีเมียมองค์กร, กระเป๋าผ้า, Licensed Merchandise, งานพิมพ์ VDP & Packaging, คลังสินค้าและ Fulfillment','ยืนหน้าโต๊ะเขียนแบบ ลูบนิ้วผ่านกระดาษสเก็ตช์ ภาพสเก็ตช์ลอยขึ้นเป็นโฮโลแกรมหมุนกลางอากาศ ตบมือครั้งเดียวโฮโลแกรมกลายเป็นของจริง กระเป๋า กระบอกน้ำ สมุด บินมาประกอบเป็นกล่องของขวัญพรีเมียมลงในมือ','สวัสดีค่ะ เชอร์รี่ จาก Mastercraftsgift และ SoonestBiz นะคะ เรามีโรงงานผลิตกระเป๋า การ์เมนต์ และของพรีเมียม พร้อมบริการ Fulfillment ครบวงจรค่ะ',null,'มีคลิป v2 แล้ว (ไม่มีซับ) รอรีวิว') on conflict (id) do nothing;
