insert into members(id,team,sort_order,code,company_th,company_en,owner_name,nickname,gender,is_leader,business,highlight,benefit,products,scene_idea,dialogue_th,contact,note) values ('move-aps-commerce','MOVE',1,null,'บริษัท เอ.พี.เอส. คอมเมิรซ จำกัด','A.P.S. Commerce Co., Ltd.','กษิตินาถ สุธีรางกูร','เจ','ชาย',false,'โลจิสติกส์และบริการติดตั้งเครื่องใช้ไฟฟ้าครบวงจร — ขนส่งทั้งแบบปกติ แช่เย็น และแช่แข็ง พร้อมทีมติดตั้งถึงบ้าน','ทำมากว่า 28 ปี ไม่ได้แค่ส่งของ แต่ติดตั้งให้ถึงบ้านด้วย ทั้งแอร์ เครื่องซักผ้า ทีวี ตู้เย็น เครื่องทำน้ำอุ่น · เป็นพาร์ตเนอร์ของ HomePro, ไทวัสดุ, Power Buy, Lotus''s, Makro, LG, Hitachi, ไปรษณีย์ไทย','ลูกค้าซื้อเครื่องใช้ไฟฟ้าแล้วได้ของถึงบ้านพร้อมติดตั้งเสร็จในครั้งเดียว ไม่ต้องหาช่างเอง','ขนส่ง Ambient/Chilled/Frozen, Express Delivery, กระจายสินค้าทั่วประเทศ, ติดตั้งเครื่องใช้ไฟฟ้าและเฟอร์นิเจอร์','กระโดดลงจากรถส่งของหน้าบ้านลูกค้า สะบัดมือครั้งเดียว กล่องทีวีและเครื่องซักผ้าลอยตามเข้าไปในบ้าน แกะกล่องเอง เข้าที่เอง ต่อสายเอง แล้วจอทีวีสว่างขึ้นพร้อมกับเครื่องซักผ้าที่เริ่มหมุน','สวัสดีครับ เจ จาก A.P.S. Commerce นะครับ เราทำขนส่งสินค้าควบคุมอุณหภูมิและติดตั้งเครื่องใช้ไฟฟ้าแบบ One Stop ครับ',null,'e-card เผยว่ามีบริการติดตั้งด้วย ไม่ใช่แค่ค้าส่ง — จุดขายอยู่ที่ ''ส่ง+ติดตั้งจบในครั้งเดียว''') on conflict (id) do nothing;
