insert into members(id,team,sort_order,code,company_th,company_en,owner_name,nickname,gender,is_leader,business,highlight,benefit,products,scene_idea,dialogue_th,contact,note) values ('move-tpi','MOVE',2,null,'บริษัท ทีพีไอ อิมปอร์ต-เอ็กซ์ปอร์ต แอนด์ ชิปปิ้ง จำกัด','TPI Import-Export & Shipping Co., Ltd.','Sarin Ye','ตาต้า','หญิง',true,'โลจิสติกส์และขนส่งระหว่างประเทศ เส้นทางไทย-จีน นำเข้าสินค้าจากจีนแบบครบวงจร','เชี่ยวชาญเส้นทางไทย-จีนโดยเฉพาะ ทำครบตั้งแต่นำเข้าทางทะเลและทางอากาศ พิธีการศุลกากร คลังสินค้า จนถึงกระจายสินค้าทั่วไทยและอาเซียน','สั่งของจากจีนแล้วมีคนดูแลให้ทุกขั้นตอน ไม่ต้องกลัวติดด่านหรือเอกสารผิด','นำเข้า-ส่งออกทางทะเล/อากาศ, พิธีการศุลกากร, คลังสินค้า, กระจายสินค้าทั่วไทยและอาเซียน','ยืนบนท่าเรืออนาคตตอนรุ่งสาง กางแผนที่โฮโลแกรมเส้นทางไทย-จีนออกกลางอากาศ ลากนิ้วตามเส้นทาง เรือคอนเทนเนอร์ลำยักษ์แล่นเข้าเทียบท่าตามนิ้ว ตู้สินค้าเรียงลงรถบรรทุกเองแล้ววิ่งออกไปตามเส้นแสงสีน้ำเงิน','สวัสดีค่ะ ตาต้า จาก TPI Import-Export & Shipping นะคะ เราดูแลโลจิสติกส์ไทย-จีน นำเข้า-ส่งออก ครบวงจรทั้งศุลกากรและคลังสินค้าค่ะ',null,'หัวหน้าทีม MOVE 🔵 — จุดขายจริงคือเส้นทางไทย-จีน ไม่ใช่ชิปปิ้งทั่วไป') on conflict (id) do nothing;
