insert into members(id,team,sort_order,code,company_th,company_en,owner_name,nickname,gender,is_leader,business,highlight,benefit,products,scene_idea,dialogue_th,contact,note) values ('move-atn','MOVE',3,'BK27114','บริษัท เอทีเอ็น โกลบอล โลจิสติก','ATN Global Logistics','วารุณี สายสินธ์','วา','หญิง',false,'ขนส่งครบวงจรทั้งในและต่างประเทศ ทางรถ ทางเรือ ทางอากาศ พร้อมคลังสินค้าปลอดอากร','รับงานที่รถทั่วไปทำไม่ได้ — เครื่องจักรหนักและสินค้าขนาดใหญ่พิเศษ · มี Free Zone Warehouse ของตัวเอง · ติดตามสถานะได้ทุกเวลา พร้อมทีมดูแลส่วนตัว','เครื่องจักรราคาหลายล้านถึงไซต์งานปลอดภัยตรงเวลา และรู้ตลอดว่าของอยู่ตรงไหน','ขนส่งทั่วไป, ขนส่งเครื่องจักรหนัก, นำเข้า-ส่งออก, คลังสินค้าปลอดอากร (Free Zone)','ยืนหน้ารถขุดคันมหึมา ยกสองแขนขึ้น รถขุดลอยไร้น้ำหนักในสนามพลังสีน้ำเงิน หมุนตัวช้าๆ แล้วค่อยๆ ลงวางบนเทรลเลอร์อย่างแม่นยำ สายรัดล็อกเองอัตโนมัติ เธอเคาะข้างรถเบาๆ รถออกวิ่งบนไฮเวย์เรืองแสง','สวัสดีค่ะ วา จาก ATN Global Logistics นะคะ เราขนส่งครบวงจรทั้งทางบก ทางเรือ ทางอากาศ พร้อมคลังสินค้า Free Zone ค่ะ',null,null) on conflict (id) do nothing;
