insert into members(id,team,sort_order,code,company_th,company_en,owner_name,nickname,gender,is_leader,business,highlight,benefit,products,scene_idea,dialogue_th,contact,note) values ('move-jaturong','MOVE',4,null,'บริษัท จตุรงค์อิมปอร์ต เอ็กซ์ปอร์ต จำกัด','Jaturong Import Export Co., Ltd.','กมลรัตน์ เต็งรุ่งโรจน์','ใบชา','หญิง',false,'ผู้ส่งออกสินค้าไทยไปตลาดเมียนมา ขายยกคอนเทนเนอร์ ดูแลครบทุกด่านชายแดน','เป็น EXPORTER ให้แบรนด์ไทยที่อยากเปิดตลาดพม่า ดูแลครบทุกด่าน — แม่สอด แม่สาย ระนอง สังขละบุรี · สินค้าที่ส่งจริงคือลิโพวิตัน-ดี ลักตาซอย น้ำมันถั่วเหลืองตราองุ่น ไวไว','แบรนด์ไทยเข้าตลาดเมียนมาได้โดยไม่ต้องไปตั้งทีมเองที่ชายแดน','ส่งออกยกคอนเทนเนอร์, สินค้าอุปโภคบริโภคไทยสู่เมียนมา','ยืนหน้าด่านชายแดนอนาคต ยกมือขึ้น ตู้คอนเทนเนอร์ที่เต็มไปด้วยสินค้าไทยลอยเรียงต่อกันเป็นสะพานแสงข้ามพรมแดนไป แล้วตู้ค่อยๆ ลงจอดฝั่งตรงข้ามอย่างเรียบร้อย','สวัสดีค่ะ ใบชา จาก Jaturong Import Export นะคะ เราเป็นผู้เชี่ยวชาญส่งออกสินค้าไทยไปเมียนมา ดูแลให้ครบทุกด่านค่ะ',null,'🎉 เดิมไม่รู้ว่าทำอะไรเลย e-card เผยว่าเป็นผู้ส่งออกไทย→เมียนมา · ยังขาดโลโก้และรูปสินค้า') on conflict (id) do nothing;
