insert into members(id,team,sort_order,code,company_th,company_en,owner_name,nickname,gender,is_leader,business,highlight,benefit,products,scene_idea,dialogue_th,contact,note) values ('move-ch-pattana','MOVE',5,'BK27054','บริษัท ช.พัฒนาคาร์เรนท์ จำกัด','CH.Pattana Car Rent Co., Ltd.','ธัญธร กิจคุณาเสถียร','กริ๊ง','หญิง',false,'ให้เช่ารถยนต์และพนักงานขับรถครบวงจร ทั้งรายวัน รายเดือน และรายปี','ราคาเช่ารวมทุกอย่างแล้ว — ประกันชั้นหนึ่ง พ.ร.บ. ภาษี ค่าซ่อมบำรุง และมีรถทดแทนตลอดอายุสัญญา · มีทั้งเก๋ง ตู้ กระบะ และรถไฟฟ้า BYD E6','องค์กรมีรถใช้ทันทีโดยไม่ต้องลงทุนซื้อ ไม่ต้องปวดหัวเรื่องซ่อม และรถไม่มีวันขาด','เช่ารถเก๋ง Toyota Altis, รถตู้ Commuter, กระบะ Revo/Isuzu, รถไฟฟ้า BYD E6, บริการพนักงานขับรถ','เดินผ่านแถวรถในลานจอดอนาคต รถตื่นขึ้นทีละคันตามจังหวะเดิน ไฟหน้าติด วงแหวนชาร์จเรืองแสง เธอสะบัดกุญแจโฮโลแกรมจากฝ่ามือส่งให้ลูกค้า รถเปิดประตูแล้วขับมาหาเขาเอง','สวัสดีค่ะ กริ๊ง จาก ช.พัฒนาคาร์เรนท์ นะคะ เราให้บริการเช่ารถยนต์พร้อมพนักงานขับรถ ครบวงจรค่ะ',null,null) on conflict (id) do nothing;
