insert into members(id,team,sort_order,code,company_th,company_en,owner_name,nickname,gender,is_leader,business,highlight,benefit,products,scene_idea,dialogue_th,contact,note) values ('grow-forth-smart','GROW',1,'BK27103','บริษัท ฟอร์ท สมาร์ท แคปปิตอล จำกัด','Forth Smart Capital Co., Ltd.','ราศิณี เลิศไตรภิญโญ','แวว','หญิง',true,'ตู้เติมเงินบุญเติม สินเชื่อสำหรับลูกค้าองค์กร และเครื่องชาร์จรถยนต์ไฟฟ้า GINKA EV','ตู้บุญเติม 130,000 ตู้ทั่วประเทศ ตัวแทนกว่า 200 ราย · ปล่อยสินเชื่อได้โดยไม่ต้องมีสาขา · เครื่องชาร์จ EV ที่ใช้ได้เลยไม่ต้องโหลดแอป จ่ายผ่าน QR ได้','คนในชุมชนเข้าถึงบริการการเงินได้ในร้านใกล้บ้าน และรถ EV ชาร์จได้ง่ายโดยไม่ต้องติดตั้งแอปเพิ่ม','ตู้บุญเติม (เติมเงิน จ่ายบิล โอนเงิน), สินเชื่อองค์กร, เครื่องชาร์จ EV AC 7.2-22 kW และ DC 40-120 kW','ยืนกลางตลาดชุมชนตอนค่ำ แตะตู้บุญเติมหนึ่งตู้ แสงสีเขียวแผ่ออกไปตามสายไฟเชื่อมต่อตู้ทุกตู้ทั่วเมืองให้สว่างขึ้นพร้อมกัน แล้วภาพถอยขึ้นสูงเห็นเป็นแผนที่แสงทั้งประเทศ','สวัสดีค่ะ แวว จาก Forth Smart Capital นะคะ เราเป็นเจ้าของตู้บุญเติมกว่า 130,000 ตู้ พร้อมสินเชื่อองค์กรและ EV Charging ค่ะ',null,'หัวหน้าทีม GROW 🟢 — ยังไม่มีรูปตู้/เครื่องชาร์จ') on conflict (id) do nothing;
