insert into members(id,team,sort_order,code,company_th,company_en,owner_name,nickname,gender,is_leader,business,highlight,benefit,products,scene_idea,dialogue_th,contact,note) values ('grow-kbank-sme','GROW',2,null,'ธนาคารกสิกรไทย (ลูกค้าผู้ประกอบการขนาดกลาง)','KASIKORNBANK','ศศิวิมล กล่อมกูล','ศศิ','หญิง',false,'รองผู้บริหารเครือข่ายธุรกิจ ดูแลลูกค้าผู้ประกอบการขนาดกลาง ให้คำปรึกษาและบริการทางการเงินแก่ธุรกิจ','เป็นคู่คิดทางการเงินที่อยู่กับธุรกิจในทุกก้าว ตั้งแต่วางแผนเติบโต ไปจนถึงหาโซลูชันทางการเงินที่เหมาะกับแต่ละธุรกิจ','เจ้าของธุรกิจมีที่ปรึกษาที่เข้าใจ ไม่ได้แค่ขายผลิตภัณฑ์ทางการเงิน','Client Relationship, Financial Advice, Business Solutions, Growth Plan','ยืนกลางเมืองยามค่ำ ยกมือขึ้น กราฟโฮโลแกรมสีเขียวที่กำลังร่วงกลับพุ่งขึ้น แล้วแตกออกเป็นเส้นแสงวิ่งไปยังร้านค้าเล็กๆ ทั่วเมือง ทำให้ไฟหน้าร้านทุกร้านสว่างขึ้นทีละร้าน','สวัสดีค่ะ ศศิ จากธนาคารกสิกรไทย SME Banking นะคะ เราดูแลสินเชื่อและโซลูชันการเงินสำหรับผู้ประกอบการ SME ค่ะ',null,'⚠️ ยังไม่มีรูปหน้าและโลโก้ในโฟลเดอร์') on conflict (id) do nothing;
