insert into members(id,team,sort_order,code,company_th,company_en,owner_name,nickname,gender,is_leader,business,highlight,benefit,products,scene_idea,dialogue_th,contact,note) values ('grow-kbank-wealth','GROW',3,null,'ธนาคารกสิกรไทย — K Private Banking / THE WISDOM','KBank Wealth Planning & Investment Advisory','เสาวนีย์ พงษ์เสนีย์','แอน','หญิง',false,'นักวางแผนการเงินและนักวิเคราะห์การลงทุน (CFP®, AISA) วางแผนการเงินครบวงจรให้เจ้าของธุรกิจ','มีใบอนุญาตวิชาชีพ CFP® และนักวิเคราะห์การลงทุน · จัดพอร์ตแบบ Holistic ครบทุกมิติ · เชี่ยวชาญวางแผนภาษีและการส่งต่อทรัพย์สินสู่รุ่นถัดไป','ทรัพย์สินที่หามาทั้งชีวิตถูกดูแลให้งอกเงยและส่งต่อได้อย่างราบรื่นและเป็นธรรม','วางแผนการเงินครบวงจร, วางแผนภาษี, วางแผนมรดก, จัดพอร์ตลงทุน, บริหารสภาพคล่อง','ยืนในห้องรับรองกระจกสูงมองเห็นเมืองทั้งเมือง ยื่นมือออก เมล็ดแสงสีทองเล็กๆ ลอยขึ้นจากฝ่ามือ แล้วค่อยๆ แตกกิ่งก้านกลายเป็นต้นไม้แสงสีทองที่เติบโตเต็มห้อง','สวัสดีค่ะ แอน จาก KBank Wealth Planning นะคะ เราเป็นที่ปรึกษาวางแผนการเงิน ภาษี และส่งต่อความมั่งคั่งสำหรับเจ้าของธุรกิจค่ะ',null,null) on conflict (id) do nothing;
