insert into members(id,team,sort_order,code,company_th,company_en,owner_name,nickname,gender,is_leader,business,highlight,benefit,products,scene_idea,dialogue_th,contact,note) values ('grow-tower-tactic','GROW',5,'BK27113','ทาวเวอร์ แทคทิค เกมส์','Tower Tactic Games','วันเฉลิม เตรียมล้ำเลิศ','แบงค์','ชาย',false,'นำเข้าและจัดจำหน่ายบอร์ดเกมลิขสิทธิ์แท้ ทั้งฉบับแปลไทยและภาษาอังกฤษ พร้อมมีหน้าร้านของตัวเอง','มีร้าน BoardgameLand 4 สาขา (Central Rama 9, Central Ladprao, The Mall บางกะปิ, The Mall บางแค) · วางขายใน Central, B2S, SE-ED, Asia Books, Kinokuniya, Shopee · จัดทัวร์นาเมนต์และสอนในคลาสการตลาด UTCC','คนไทยได้เล่นบอร์ดเกมระดับโลกเป็นภาษาไทย และมีที่ให้ไปลองเล่นจริงก่อนซื้อ','Spyfall, Camel Up, Babel, Kushi Express, โยชิ, Sushi Go!, Century Golem และอีกมาก','ยืนหน้าโต๊ะเปล่าในบ้านอนาคต โยนกล่องบอร์ดเกมขึ้นกลางอากาศ กล่องเปิดออก การ์ด เบี้ย และกระดานลอยกระจายแล้วลงจัดวางบนโต๊ะเองอย่างเป็นระเบียบ รอบโต๊ะมีเงาคนหัวเราะกันเต็มวง','สวัสดีครับ แบงค์ จาก Tower Tactic Games นะครับ เรามีบอร์ดเกมลิขสิทธิ์แท้ ร้าน BoardgameLand และกิจกรรม Team Building ครับ',null,null) on conflict (id) do nothing;
