insert into members(id,team,sort_order,code,company_th,company_en,owner_name,nickname,gender,is_leader,business,highlight,benefit,products,scene_idea,dialogue_th,contact,note) values ('live-damrong','LIVE',1,'BK27007','กุ้งดำรงค์','Damrong Shrimp','กัมปนาท สง่าเพ็ชร','เบียร์','ชาย',false,'จำหน่ายกุ้งสดและอาหารทะเล ส่งร้านอาหารและผู้บริโภค พร้อมบริการแกะกุ้งตามสั่ง','สนับสนุนเกษตรกรเลี้ยงกุ้งในสมุทรปราการมากว่า 40 ปี · คัดไซส์เป๊ะตามสั่ง · มีบริการแกะเปลือกให้ · ส่งร้านอาหารไวใน 1 ชั่วโมง และส่งทั่วประเทศใน 24 ชั่วโมง','ได้กุ้งสดจริง ไซส์ตรงตามสั่ง พร้อมปรุงทันทีโดยไม่ต้องเสียเวลาแกะเอง','กุ้งสดคัดไซส์, กุ้งแกะเปลือกตามสั่ง, จัดส่งทั่วประเทศ','วิ่งแล้วพุ่งดำลงบ่อกุ้ง ใต้น้ำจับกุ้งตัวใหญ่ได้ด้วยมือเปล่า แล้วทะยานขึ้นเหนือผิวน้ำพร้อมกุ้งในมือ น้ำกระจายเป็นละอองรอบตัว','สวัสดีครับ เบียร์ จากกุ้งดำรงค์ นะครับ เรามีกุ้งสดคุณภาพ ทั้งค้าส่งและค้าปลีก จัดส่งทั่วประเทศภายใน 24 ชั่วโมงครับ',null,'✅ คลิปผ่านแล้ว') on conflict (id) do nothing;
