insert into members(id,team,sort_order,code,company_th,company_en,owner_name,nickname,gender,is_leader,business,highlight,benefit,products,scene_idea,dialogue_th,contact,note) values ('live-yoksod','LIVE',2,'BK27097','หยกสด','Yok Sod','มหศักย์ สุรกิจบวร','จ๊าก','ชาย',false,'ผลิตและจำหน่ายขนมไทยใบเตยแท้ 100%','ใช้ใบเตยแท้ 100% ไม่ใช้กลิ่นสังเคราะห์ ทำตามสูตรโบราณ เนื้อขนมสีเขียวใสเหมือนหยก จึงเป็นที่มาของชื่อ ''หยกสด'' — ของมีค่าที่กินได้','ได้กินขนมไทยแท้ที่หากินยากขึ้นทุกวัน ไม่ใช่รสสังเคราะห์','ขนมไทยใบเตยสูตรโบราณ เสิร์ฟในถ้วยเบญจรงค์ ราดกะทิสด','ลูบใบเตยในไร่ แสงสีเขียวหยกพวยพุ่งขึ้นจากใบ ไหลวนมารวมกันในมือ แล้วก่อตัวเป็นเม็ดขนมใบเตยใสเหมือนหยกตกลงในถ้วยเบญจรงค์','สวัสดีครับ จ๊าก จากหยกสด นะครับ เราทำขนมไทยใบเตยแท้ 100% หอมอร่อยแบบต้นตำรับครับ',null,'✅ คลิปผ่านแล้ว — e-card ยืนยันว่าเจ้าของเป็นผู้ชาย (จ๊าก)') on conflict (id) do nothing;
