insert into members(id,team,sort_order,code,company_th,company_en,owner_name,nickname,gender,is_leader,business,highlight,benefit,products,scene_idea,dialogue_th,contact,note) values ('live-sirichai','LIVE',3,'BK27096','ตราศิริชัย','Sirichai Brand / LENA PRO','มนรินทร์ เลิศวรทวี','เจิน','หญิง',false,'ผู้ผลิตและจัดจำหน่ายนมแพะ UHT รับผลิต OEM นม UHT และจำหน่ายเม็ดมะม่วงหิมพานต์คัดพรีเมียม','นมแพะ UHT ครบ 4 รส (จืด ช็อกโกแลต ถั่วเหลือง โฟเลต+B12) · มีแบรนด์ใหม่ LENA PRO โปรตีนสูง 15 กรัม แลคโตส 0% ไขมัน 0% · รับผลิต OEM ให้แบรนด์อื่นได้','ทางเลือกนมที่ย่อยง่ายและโปรตีนสูง เก็บได้นานไม่ต้องแช่เย็น','นมแพะ UHT 4 รส, LENA PRO High Protein 15g, เม็ดมะม่วงหิมพานต์, รับผลิต OEM','ยืนกลางฟาร์มแพะยามเช้า ยกมือขึ้น กล่องนมแพะ UHT ลอยเรียงเป็นแถวรอบตัว น้ำนมสีขาวไหลเป็นสายลงเติมทีละกล่องเอง ข้างๆ เม็ดมะม่วงหิมพานต์หมุนเป็นเกลียวสีทองลงบรรจุซอง','สวัสดีค่ะ เจิน จากตราศิริชัย และ LENA PRO นะคะ เราทำนมแพะ UHT และนมโปรตีนสูง คุณภาพสำหรับทุกวัยค่ะ',null,'✅ คลิป v1 ผ่านแล้ว แต่ e-card เผยว่าพระเอกคือนมแพะ UHT + LENA PRO ไม่ใช่เม็ดมะม่วง ถ้ามีเวลาควร regen') on conflict (id) do nothing;
