insert into members(id,team,sort_order,code,company_th,company_en,owner_name,nickname,gender,is_leader,business,highlight,benefit,products,scene_idea,dialogue_th,contact,note) values ('live-vejpong','LIVE',4,'BK27068','น้ำผึ้งเวชพงศ์','Vejpong Natural Honey','เบญจรัตน์ เวชพงศา','เบญ','หญิง',false,'ผลิตและจำหน่ายน้ำผึ้งธรรมชาติ แบรนด์น้ำผึ้งเวชพงศ์','น้ำผึ้งคุณภาพฉลากสีน้ำเงินที่เป็นเอกลักษณ์ของแบรนด์ มีทั้งแบบขวดและกระปุกหลายขนาด','ได้น้ำผึ้งแท้ที่รู้ที่มา ไม่ต้องเดาว่าผสมอะไรมาบ้าง','น้ำผึ้งธรรมชาติ ฉลากสีน้ำเงิน หลายขนาด','นั่งดูแลรังผึ้งอย่างอ่อนโยนในสวนตอนเช้า ผึ้งบินวนเป็นเกลียวรอบตัวอย่างเป็นมิตร แล้วน้ำผึ้งสีทองไหลเป็นสายลงขวดฉลากน้ำเงินในมือเธอเอง','สวัสดีค่ะ เบญ จากน้ำผึ้งเวชพงศ์ นะคะ เราคัดน้ำผึ้งธรรมชาติแท้ 100% คุณภาพส่งตรงจากรังค่ะ',null,'✅ คลิปผ่านแล้ว') on conflict (id) do nothing;
