insert into members(id,team,sort_order,code,company_th,company_en,owner_name,nickname,gender,is_leader,business,highlight,benefit,products,scene_idea,dialogue_th,contact,note) values ('live-aday-fresh','LIVE',5,'BK27057','อะเดย์ เฟรช','aDay Fresh','รัญวรัตน์ รุ่งโรจน์วิทยกุล','กอล์ฟ','หญิง',true,'ผู้ก่อตั้งและบริหาร 5 ธุรกิจ — aDay Fresh (ผลไม้พรีเมียมออนไลน์), joolz (น้ำผลไม้คั้นสด B2B/OEM), abc (ร้านแม่และเด็ก 3 สาขา), CODELAB (สอนโค้ดดิ้งและโรบอติกส์เด็ก), AOO Commerce (ระบบจัดการธุรกิจออนไลน์)','aDay Fresh ได้รับความไว้วางใจจากลูกค้าหลักแสนคน · คัดผลไม้ทีละลูก ออกแบบกระเช้าสวยทุกโอกาส และจัดส่งตรงเวลาด้วยความใส่ใจ · เป็นผู้ประกอบการที่ต่อยอดได้ถึง 5 ธุรกิจ','ส่งความห่วงใยให้คนสำคัญได้ตรงเวลา สวย และสดใหม่ โดยไม่ต้องไปเลือกเอง','กระเช้าผลไม้พรีเมียม, ผลไม้นำเข้า, น้ำผลไม้คั้นสด joolz, สินค้าแม่และเด็ก, คอร์สโค้ดดิ้งเด็ก, ระบบ AOO Commerce','วิ่งด้วยความเร็วสูงเข้าไปในสวนผลไม้ เด็ดผลไม้แบบไวจนเป็นภาพเบลอลงกระเช้า แล้ววิ่งต่อไปถึงหน้าบ้านลูกค้า หยิบกระเช้าออกจากกล่องยื่นให้พร้อมรอยยิ้ม','สวัสดีค่ะ กอล์ฟ จาก aDay Fresh นะคะ เราทำผลไม้พรีเมียมและน้ำผลไม้คั้นสด สำหรับกระเช้าของขวัญและลูกค้าองค์กรค่ะ',null,'หัวหน้าทีม LIVE 🌸 · ✅ คลิปผ่านแล้ว') on conflict (id) do nothing;
