insert into members(id,team,sort_order,code,company_th,company_en,owner_name,nickname,gender,is_leader,business,highlight,benefit,products,scene_idea,dialogue_th,contact,note) values ('live-pchw','LIVE',6,'BK27059','ปตท. ปากช่องไฮเวย์ (พีซีเอชดับบลิว)','PCHW — PTT Station & Cafe Amazon & Chill Hotel','ธีรวัจน์ บุญเจริญกิจจา','ธีร์','ชาย',false,'ผู้ประกอบการหลายธุรกิจบนเส้นทางปากช่อง-เขาใหญ่-สระบุรี — สถานีบริการ PTT 6 สาขา, 7-Eleven, Cafe Amazon 12 สาขา, ร้านของฝากของหวาน และโรงแรม','คุมทั้งเส้นทางท่องเที่ยวปากช่อง-เขาใหญ่-สระบุรี ตั้งแต่ปั๊มน้ำมัน ร้านกาแฟ ร้านของฝาก ไปจนถึงโรงแรม CHILL HOTEL (นอนชิลล์ เขาใหญ่, ชิลล์ เขาใหญ่)','คนขับทางไกลและนักท่องเที่ยวมีจุดพักที่ครบและไว้ใจได้ตลอดเส้นทาง','PTT Station, 7-Eleven, Cafe Amazon, ร้านของฝาก/ของหวาน, โรงแรม CHILL HOTEL','เดินเข้าไปหาคนขับรถบรรทุกที่นั่งเหนื่อยล้าอยู่ตอนดึก ยื่นแก้วกาแฟให้ แสงอุ่นสีชมพูแผ่ออกจากแก้ว ความเหนื่อยบนใบหน้าคนขับหายไป เขาลุกขึ้นยืนตัวตรงแล้วยิ้ม','สวัสดีครับ ธีร์ จาก PTT ปากช่องไฮเวย์ นะครับ เราดูแลปั๊ม PTT, Cafe Amazon, Dairy Queen และโรงแรมชิลล์ เขาใหญ่ ครบในที่เดียวครับ',null,'✅ คลิปผ่านแล้ว') on conflict (id) do nothing;
