insert into members(id,team,sort_order,code,company_th,company_en,owner_name,nickname,gender,is_leader,business,highlight,benefit,products,scene_idea,dialogue_th,contact,note) values ('thrive-winds','THRIVE',1,'BK27021','โรงพยาบาลวินด์ส และ วินด์ คลินิก','Winds Hospital & Wind Clinic','นพ. เฉลิมชัย ศรีอัครพงศ์','Bazz','ชาย',true,'โรงพยาบาลศัลยกรรมตกแต่งเฉพาะทางและคลินิกเวชศาสตร์ความงามครบวงจร จ.อุบลราชธานี','เป็นโรงพยาบาลจริง ไม่ใช่คลินิก มีมาตรฐานความปลอดภัยระดับโรงพยาบาล · ผู้ก่อตั้งเป็นอาจารย์แพทย์ของ Allergan Medical Institute และเป็นวิทยากรระดับเอเชีย · บุกเบิกเวชศาสตร์ความงามในอีสานตอนล่าง','คนต่างจังหวัดได้รับการดูแลมาตรฐานโรงพยาบาลโดยไม่ต้องเดินทางเข้ากรุงเทพ','ศัลยกรรมตกแต่ง (Plastic Surgery), ออกแบบใบหน้า (Facial Design & Rejuvenation), ดูแลรูปร่างโดยแพทย์ (Medical Weight Loss)','ยืนในโถงโรงพยาบาลอนาคตสีขาวสะอาด ยกมือขึ้น กระจกบานใหญ่ตรงหน้าค่อยๆ ใสขึ้น สะท้อนภาพคนไข้ที่ยืนตัวตรงขึ้น ยิ้มอย่างมั่นใจ แล้วเดินออกไปหาแสง','สวัสดีครับ หมอเฉลิมชัย จาก Winds Hospital และ Wind Clinic นะครับ เราเป็นโรงพยาบาลศัลยกรรมตกแต่งและเวชศาสตร์ความงาม จังหวัดอุบลราชธานีครับ',null,'หัวหน้าทีม THRIVE 🩵 — เนื้อหาต้นทางเป็นโฆษณาศัลยกรรม ควรเล่าเชิงความมั่นใจ ไม่โชว์เรือนร่าง') on conflict (id) do nothing;
