insert into members(id,team,sort_order,code,company_th,company_en,owner_name,nickname,gender,is_leader,business,highlight,benefit,products,scene_idea,dialogue_th,contact,note) values ('thrive-rebalance','THRIVE',2,'BK27073','รีบาลานซ์ คลินิกกายภาพบำบัด','Rebalance','ปุณยกานต์ กิตติโสภิดาดิษฐ์','ปูเป้','หญิง',false,'คลินิกกายภาพบำบัด 22 สาขา ในกรุงเทพ ปริมณฑล และภาคตะวันออก','มีเทคนิคเฉพาะของตัวเองชื่อ ''EaseMotion'' ที่ฟื้นฟูอาการปวดจากต้นเหตุ · ดูแลโดยนักกายภาพบำบัดวิชาชีพทุกเคส · ออกแบบการรักษาเฉพาะบุคคล · คืนอิสระการเคลื่อนไหวให้คนมาแล้วกว่า 100,000 ราย','อาการปวดเรื้อรังหายจากต้นเหตุจริง ไม่ใช่หายชั่วคราวแล้วกลับมาปวดอีก','EaseMotion, Balance Massage, Balance Stretch, โปรแกรมกายภาพบำบัดเฉพาะบุคคล','ยืนข้างคนไข้ที่กำลังก้มตัวด้วยความปวด วางมือลงบนหลัง เส้นแสงสีแดงตามแนวกระดูกสันหลังค่อยๆ เปลี่ยนเป็นสีเขียวมิ้นท์ไล่ขึ้นไป คนไข้ยืดตัวตรงขึ้นและหายใจโล่ง','สวัสดีค่ะ ปูเป้ จาก Rebalance นะคะ เราเป็นคลินิกกายภาพบำบัด 22 สาขา ด้วยเทคนิคเฉพาะ EaseMotion ค่ะ',null,null) on conflict (id) do nothing;
