insert into members(id,team,sort_order,code,company_th,company_en,owner_name,nickname,gender,is_leader,business,highlight,benefit,products,scene_idea,dialogue_th,contact,note) values ('thrive-joyous','THRIVE',3,'BK27004','จอยอัส','Joyous — Beauty & Personal Care Accessories','กวิน ศุภกฤตกุล','อู๋','ชาย',false,'จัดจำหน่ายและค้าปลีกอุปกรณ์ความงามและของใช้ส่วนตัว แบรนด์ JOYOUS','ครบทั้ง 4 หมวด — อุปกรณ์คิ้ว เล็บ ขนตา และเครื่องมือแต่งหน้า · สโลแกน ''สะดวก & สวย ได้ในทุกวัน'' · ตะไบมีให้เลือกทั้งเนื้อหยาบ กลาง ละเอียด','ของใช้ชิ้นเล็กที่ใช้ทุกวัน คมและทน ไม่ต้องซื้อใหม่บ่อย','กรรไกรตัดเล็บ, คีมตัดหนัง, แหนบ, มีดโกนคิ้ว, ตะไบเล็บ, ที่ดัดขนตา, แปรงแต่งหน้า','ยืนหน้าโต๊ะสีขาวสะอาด อุปกรณ์สเตนเลสชิ้นเล็กๆ ลอยขึ้นเรียงเป็นแถวรอบตัวและสะท้อนแสงเป็นประกาย แล้วลงบรรจุในแพ็กสีชมพูทีละชิ้นอย่างพอดี','สวัสดีครับ อู๋ จาก Joyous นะครับ เราทำอุปกรณ์ความงามและของใช้ประจำวัน Beauty Tools คุณภาพครับ',null,null) on conflict (id) do nothing;
