insert into members(id,team,sort_order,code,company_th,company_en,owner_name,nickname,gender,is_leader,business,highlight,benefit,products,scene_idea,dialogue_th,contact,note) values ('thrive-leviya','THRIVE',4,'BK27118','เลวิญา','L''EVIYA — Luxury Wellness & Body Restoration','ดร. วิรินญา เลิศพัฒนกิจ','โน้ต','หญิง',false,'ธุรกิจ wellness 3 แบรนด์ — L''EVIYA (ฟื้นฟูสุขภาพและรูปร่าง), อยู่ไฟคุณหมอ (ฟื้นฟูคุณแม่หลังคลอด), BABY BELLS (ดูแลทารกแรกเกิด 0-3 เดือน)','ใช้ศาสตร์การแพทย์แผนไทยประยุกต์ผสานวิทยาศาสตร์และเทคโนโลยี ดูแลโดยผู้ประกอบวิชาชีพแพทย์แผนไทยประยุกต์ · โปรแกรมหลังคลอดครอบคลุมถึงภาวะกล้ามเนื้อหน้าท้องแยก (Diastasis Recti) และการดูแลแผลเป็น · คำโปรย ''เพราะการทำให้ผู้หญิงสวย คือความภูมิใจของเรา''','คุณแม่หลังคลอดได้ร่างกายกลับมาเป็นตัวเอง และมีคนช่วยดูแลลูกแรกเกิดอย่างมืออาชีพ','L''EVIYA Body Restoration & Detox, อยู่ไฟคุณหมอ (ฟื้นฟูหลังคลอด), BABY BELLS (ผู้ช่วยดูแลทารกแรกเกิด)','ยืนในห้องทรีตเมนต์สีครีมอบอุ่น วางมือเหนือคุณแม่ที่นอนพัก แสงสีเขียวหยกอ่อนโยนไหลจากมือลงไปตามลำตัว เธอค่อยๆ ลุกขึ้นนั่งได้เอง ยิ้ม แล้วรับลูกน้อยมากอด','สวัสดีค่ะ โน้ต จาก L''EVIYA นะคะ เราให้บริการ Luxury Wellness อยู่ไฟหลังคลอดและดูแลทารกแรกเกิดค่ะ',null,'⚠️ ยังไม่มีรูปหน้า/โลโก้/รูปสินค้าในโฟลเดอร์ มีแต่ e-card') on conflict (id) do nothing;
