insert into script_sections(key,title_th,body,sort_order) values ('problem-make','😰 ฉากปัญหา — MAKE','สินค้าดีแต่แพ็กเกจจิ้งไม่ดึงดูด วางบนชั้นแล้วไม่มีใครหยิบ ของเสียหายระหว่างขนส่ง',11) on conflict (key) do update set title_th=excluded.title_th, body=excluded.body;
insert into script_sections(key,title_th,body,sort_order) values ('problem-move','😰 ฉากปัญหา — MOVE','ลานรถขนส่งที่รถจอดนิ่ง ตู้คอนเทนเนอร์กองไม่ได้ออก ของติดด่าน ส่งไม่ทัน',12) on conflict (key) do update set title_th=excluded.title_th, body=excluded.body;
insert into script_sections(key,title_th,body,sort_order) values ('problem-grow','😰 ฉากปัญหา — GROW','กราฟยอดขายที่ร่วงลง เงินหมุนไม่ทัน หาคนทำงานไม่ได้',13) on conflict (key) do update set title_th=excluded.title_th, body=excluded.body;
insert into script_sections(key,title_th,body,sort_order) values ('problem-live','😰 ฉากปัญหา — LIVE','ของสดที่เสียก่อนถึงมือลูกค้า ตลาดเงียบ ราคาผลผลิตตก',14) on conflict (key) do update set title_th=excluded.title_th, body=excluded.body;
insert into script_sections(key,title_th,body,sort_order) values ('problem-thrive','😰 ฉากปัญหา — THRIVE','คนที่เหนื่อยล้า ปวดเรื้อรัง หมดความมั่นใจในตัวเอง',15) on conflict (key) do update set title_th=excluded.title_th, body=excluded.body;
